CREATE TABLE public.onedrive_worker_keys(user_id uuid PRIMARY KEY,token text NOT NULL DEFAULT encode(gen_random_bytes(32),'hex'),created_at timestamptz NOT NULL DEFAULT now()); GRANT ALL ON public.onedrive_worker_keys TO service_role; ALTER TABLE public.onedrive_worker_keys ENABLE ROW LEVEL SECURITY; INSERT INTO public.onedrive_worker_keys(user_id) SELECT user_id FROM public.onedrive_access; CREATE EXTENSION IF NOT EXISTS pg_cron; CREATE EXTENSION IF NOT EXISTS pg_net;